-- Balloon Zone Dubai — MySQL schema (DRAFT, not deployed)
-- Generated 2026-11-11 from src/lib/products.ts + src/lib/admin.ts
-- (20 products, verified prices kept). Run in phpMyAdmin on Rank's own
-- hosting when cPanel access is available. DB name in cPanel is usually
-- prefixed (e.g. username_balloon_zone) — adjust the CREATE DATABASE line.
-- MySQL 5.7+ / MariaDB 10.2.7+ (JSON columns). Demo login admin/admin123
-- from admin.ts MUST NOT go live — set a real password in admin_users.
-- WARNING: anything entered in the demo /admin CMS lives only in that
-- browser's localStorage and will NOT carry over automatically.

CREATE DATABASE IF NOT EXISTS balloon_zone CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE balloon_zone;

CREATE TABLE IF NOT EXISTS products (
  slug VARCHAR(60) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  price INT NOT NULL,
  was_price INT NULL,
  category VARCHAR(100) NOT NULL,
  occasion VARCHAR(100) NOT NULL,
  image VARCHAR(512) NOT NULL,
  blurb VARCHAR(512) NOT NULL,
  verified TINYINT(1) NOT NULL DEFAULT 0,
  badge VARCHAR(50) NULL,
  description JSON NOT NULL,
  suitable_for JSON NOT NULL,
  includes_list JSON NOT NULL,
  visible TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS orders (
  id VARCHAR(32) PRIMARY KEY,
  order_date DATETIME NOT NULL,
  customer VARCHAR(255) NOT NULL,
  phone VARCHAR(50) NOT NULL,
  address TEXT NOT NULL,
  subtotal INT NOT NULL,
  delivery INT NOT NULL DEFAULT 29,
  total INT NOT NULL,
  status ENUM('Pending','Confirmed','Processing','In Transit','Delivered','Cancelled') NOT NULL DEFAULT 'Pending',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS order_items (
  id INT AUTO_INCREMENT PRIMARY KEY,
  order_id VARCHAR(32) NOT NULL,
  name VARCHAR(255) NOT NULL,
  qty INT NOT NULL,
  price INT NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS callbacks (
  id VARCHAR(32) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  phone VARCHAR(50) NOT NULL,
  time VARCHAR(50) NOT NULL,
  request_date DATETIME NOT NULL,
  status ENUM('New','Called') NOT NULL DEFAULT 'New',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS coupons (
  code VARCHAR(32) PRIMARY KEY,
  percent INT NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  note VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS settings (
  id INT PRIMARY KEY DEFAULT 1,
  store_name VARCHAR(255) NOT NULL,
  phone VARCHAR(50) NOT NULL,
  whatsapp VARCHAR(50) NOT NULL,
  email VARCHAR(255) NOT NULL,
  delivery_fee INT NOT NULL DEFAULT 29,
  free_delivery_threshold INT NOT NULL DEFAULT 500
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS admin_users (
  username VARCHAR(50) PRIMARY KEY,
  password_hash VARCHAR(255) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Seeds from admin.ts defaults (DEFAULT_SETTINGS, SEED_COUPONS).
