INSERT INTO products (slug, name, price, was_price, category, occasion, image, blurb, verified, badge, description, suitable_for, includes_list) VALUES ('luxury-birthday-gala-package', 'Luxury Birthday Gala Package', 1300, NULL, 'Decoration Packages', 'Birthday', 'https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=900&q=80', 'Full gala balloon decoration, delivered and installed in Dubai.', 1, 'Bestseller', '["Make the birthday feel like a gala. Our Luxury Birthday Gala Package turns your venue into a show-stopping celebration, with a full balloon garland in rich party colours, a photo-worthy backdrop and elegant foil accents that set the scene the moment guests walk in.", "Our team delivers and installs everything at your home, hotel or venue in Dubai, then styles the final details so the setup looks picture-perfect from every angle. Order before 6 PM for same-day delivery, and let us handle the decorating while you enjoy the party."]', '["Milestone birthdays", "Hotel and villa parties", "Birthday dinners and gatherings", "Photo shoots and reels", "Surprise birthday celebrations"]', '["Full balloon garland in party colours", "Decorated backdrop for photos", "Foil number and accent balloons", "Table and entrance styling", "Delivery and professional installation in Dubai"]') ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), was_price=VALUES(was_price), image=VALUES(image);
INSERT INTO products (slug, name, price, was_price, category, occasion, image, blurb, verified, badge, description, suitable_for, includes_list) VALUES ('classic-cocoa-birthday-cake', 'Classic Cocoa Birthday Cake', 190, NULL, 'Cakes & Sweets', 'Birthday', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=900&q=80', 'Rich cocoa cake, made for birthdays and every sweet celebration.', 1, NULL, '["A birthday classic, done properly. Our Classic Cocoa Birthday Cake is rich, moist and deeply chocolatey, baked fresh and finished with smooth cocoa frosting for a cake that looks as good as it tastes.", "It arrives ready to serve at your celebration, carefully packed and delivered in Dubai. Order before 6 PM for same-day delivery and add a candle moment your guests will remember."]', '["Birthday parties", "Family gatherings", "Office birthday surprises", "Cake-cutting moments", "Chocolate lovers of all ages"]', '["Freshly baked cocoa birthday cake", "Smooth cocoa frosting finish", "Decorative cake topper", "Careful gift packaging", "Same-day delivery in Dubai"]') ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), was_price=VALUES(was_price), image=VALUES(image);
INSERT INTO products (slug, name, price, was_price, category, occasion, image, blurb, verified, badge, description, suitable_for, includes_list) VALUES ('blush-glow-ring-package', 'Blush & Glow Ring Package', 1200, NULL, 'Decoration Packages', 'Proposal', 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=900&q=80', 'Blush and glow ring setup for proposals and romantic moments.', 1, NULL, '["Pop the question in front of a ring that glows. The Blush & Glow Ring Package frames the moment with a beautiful balloon ring in soft blush tones, warm glowing accents and romantic styling made for proposals.", "Our team sets it up at your chosen spot — a hotel room, a villa garden or a restaurant corner — so all you have to do is ask. Same-day delivery is available for orders before 6 PM."]', '["Marriage proposals", "Romantic surprises", "Anniversary celebrations", "Engagement photos", "Hotel room setups"]', '["Blush balloon ring installation", "Warm glow lighting accents", "Romantic floor and table styling", "Foil heart accents", "Delivery and professional setup in Dubai"]') ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), was_price=VALUES(was_price), image=VALUES(image);
